+    border: 1px solid #dee2e6;
+    border-radius: 8px;
+    transition: all 0.2s;
+}
+
+.preview-area h4 {
+    margin-bottom: 0.5rem;
+}
+
+.preview-card {
+    margin-top: 0.75rem;
+    padding: 1rem;
+    border: 1px solid #e0e0e0;
+    border-radius: 4px;
+}
+
+.preview-light {
+    background: #ffffff;
+    color: #333;
+}
+
+.preview-dark {
+    background: #1e1e1e;
+    color: #e0e0e0;
+    border-color: #444;
+}
+
+.preview-dark .preview-card {
+    background: #2d2d2d;
+    border-color: #555;
+}
+
+.preview-system {
+    background: #f5f5f5;
+    color: #333;
+}
+
+.preview-font-small {
+    font-size: 0.8rem;
+}
+
+.preview-font-medium {
+    font-size: 1rem;
+}
+
+.preview-font-large {
+    font-size: 1.2rem;
+}
+
+.preview-area.compact {
+    padding: 0.75rem;
+}
+
+.preview-area.compact .preview-card {
+    padding: 0.5rem;
+    margin-top: 0.4rem;
